from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]

    groups = []
    start = None
    for r, row in enumerate(grid):
        active = any(value != background for value in row)
        if active and start is None:
            start = r
        elif not active and start is not None:
            groups.append((start, r))
            start = None
    if start is not None:
        groups.append((start, h))

    out = [row[:] for row in grid]
    candidates = []
    for i, (source_start, source_end) in enumerate(groups):
        for j, (target_start, target_end) in enumerate(groups):
            if i == j or source_end - source_start != target_end - target_start:
                continue
            height = source_end - source_start
            for shift in range(-3, 4):
                left = max(0, shift)
                right = min(w, w + shift)
                overlap = right - left
                if overlap < w - 3:
                    continue

                missing = []
                exact = 0
                valid = True
                for offset in range(height):
                    for c in range(left, right):
                        expected = grid[source_start + offset][c - shift]
                        actual = grid[target_start + offset][c]
                        if expected == actual:
                            exact += 1
                        elif expected != background and actual == background:
                            missing.append((target_start + offset, c))
                        else:
                            valid = False
                            break
                    if not valid:
                        break

                if valid and missing:
                    candidates.append((exact, -len(missing), overlap, missing))

    if candidates:
        best = max(candidates, key=lambda item: (item[0], item[1], item[2]))
        for r, c in best[3]:
            out[r][c] = 1
    return out
